INSERT INTO public.form_section (id, form_id, title, description, "position", is_active, version) VALUES (1, 1, '{}', '{"en": "This is **the application form for the mestrado''s in Computer Science program at the Institute of Mathematics and Statistics of the University of São Paulo**. The form has five parts:

- Personal information;\n
- academic information;\n
- professional information;\n
- research interests and additional information;\n
- document submission.\n

It is also recommended that you familiarize yourself with the [program''s research areas](https://www.ime.usp.br/dcc/areas-pesquisa) and your interests.
", "pt": "Este é o **formulário de inscrição no processo seletivo para mestrado em Ciência da Computação do Instituto de Matemática e Estatística da Universidade de São Paulo**, para ingresso em **2026**. O formulário conta com 5 partes:\n 
- Dados pessoais;\n
- dados acadêmicos;\n
- dados profissionais;\n
- interesses de pesquisa e dados adicionais;\n
- envio de documentos.\n

Também é recomendado que você se informe apropriadamente sobre as [linhas de pesquisa do programa](https://www.ime.usp.br/dcc/areas-pesquisa) e seu interesse.
"}', 0, true, 1);
