INSERT INTO public.form_field (id, form_id, section_id, label, name, description, type, placeholder, required, disabled, validation, error_message, prefix, "position", is_active, version) VALUES (14, 1, 2, '{"en": "Professional page", "pt": "Página profissional"}', 'website', '{"en": "
Professional webpage address, such as LinkedIn, online CV, or portfolio.\n

