INSERT INTO public.form_field (id, form_id, section_id, label, name, description, type, placeholder, required, disabled, validation, error_message, prefix, "position", is_active, version) VALUES (16, 1, 2, '{"en": "Medical Certificate (Severe Disability - PCD)", "pt": "Laudo médico comprobatório (PCD grave)"}', 'disabilities-file', '{"en": "
Please upload a medical certificate proving your condition of severe disability, in accordance with the Brazilian Law for the Inclusion of Persons with Disabilities (Law No. 13,146/2015).\n

*This upload is required only for candidates who identify as having a severe disability (PCD).*
", "pt": "
